{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C19", "C120", "C102", "C125", "C129", "C96"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C19", "C120", "C102", "C125"],
  "claims": [
    {
      "claim": "Cefuroxime axetil, the closest human-measured analog sharing the cephem core, 3-carbamoyloxymethyl, and acyloxyalkyl ester prodrug strategy, has 64% absolute oral bioavailability (90% CI 58-69%) after a 500 mg oral dose, directly supporting F >= 20% for this prodrug class.",
      "card_ids": ["C19"]
    },
    {
      "claim": "L4 intestinal evidence for cefuroxime axetil shows moderate permeability consistent with its measured 64% F: Caco-2 Papp of 13.3 x10^-7 cm/s and in situ proximal intestinal P_eff of 0.31 x10^-4 cm/s, with 100% dissolution of the amorphous form within 60 minutes.",
      "card_ids": ["C102", "C125", "C129"]
    },
    {
      "claim": "Human absorption studies show pivampicillin, an acyloxyalkyl ester prodrug of ampicillin, was absorbed almost quantitatively, and cefcapene pivoxil showed Caco-2 Papp of 7.85 x10^-6 cm/s, supporting good intestinal absorption of beta-lactam ester prodrugs.",
      "card_ids": ["C120", "C96"]
    },
    {
      "claim": "No L4 record affirmatively supports F < 20% for the query; low-permeability records concern atenolol as a paracellular marker and poor plain-drug dissolution of cefpodoxime proxetil is formulation-specific, so neither transfers as a negative query outcome.",
      "card_ids": ["C94", "C117"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C102", "C125", "C129", "C120", "C96"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule.",
    "No human PK, dose, formulation, or IV-comparator data for the query.",
    "The query's 7-hydroxyethyl substituent and acetoxymethyl ester differ from cefuroxime axetil's acylamino side chain and 1-acetoxyethyl ester, so permeability and esterase stability may differ.",
    "L4 permeability records are for related ester prodrugs rather than the query; the query's lower estimated logD (-0.73) could reduce permeability relative to cefuroxime axetil."
  ],
  "decision_summary": "Predicted high because the closest human-measured analog cefuroxime axetil has 64% absolute oral bioavailability, L4 intestinal permeability and dissolution records for beta-lactam acyloxyalkyl ester prodrugs support adequate absorption, and no affirmative threshold-relevant evidence supports F < 20%."
}

